+
+function renderTemplate(source: string, context: TemplateContext, partials: Map<string, string>): string {
+  let rendered = source.replace(/{{!--[\s\S]*?--}}|{{!.*?}}/g, '');
+  const block = /{{#(if|unless|each)\s+([^}]+)}}([\s\S]*?){{\/\1}}/g;
